const asyncTaskHandler = () => {
  const taskQueue = [];

  const addTask = (taskFn) => {
    taskQueue.push(taskFn);
    processTasks();
  };

  const processTasks = () => {
    if (taskQueue.length === 0) return;

    const taskFn = taskQueue.shift();

    try {
      const taskPromise = taskFn();

      if (!isPromise(taskPromise)) {
        throw new Error("Task must return a promise");
      }

      taskPromise
        .then(() => {
          processTasks();
        })
        .catch((error) => {
          console.error("An error occurred:", error);
          processTasks();
        });
    } catch (error) {
      console.error("An error occurred:", error);
      processTasks();
    }
  };

  const isPromise = (value) => {
    return value && typeof value.then === "function";
  };

  return {
    addTask,
  };
};

