import org.junit.Assert;
import org.junit.Test;

public class FibonacciSumTest {

    @Test
    public void testFibonacciSum() {
        // Testing the sum of Fibonacci numbers: 2 + 3 + 5 = 10
        int expectedSum = 10;
        int[] fibonacciNumbers = generateFibonacciNumbers(3);
        int actualSum = fibonacciNumbers[0] + fibonacciNumbers[1] + fibonacciNumbers[2];
        Assert.assertEquals(expectedSum, actualSum);

        // Testing if the sum is a prime number
        boolean isPrime = isPrime(actualSum);
        Assert.assertTrue(isPrime);
    }

    // Method to generate Fibonacci numbers efficiently without recursion
    private int[] generateFibonacciNumbers(int n) {
        if (n < 2)
            throw new IllegalArgumentException("n must be greater than or equal to 2");

        int[] fibonacciNumbers = new int[n];
        fibonacciNumbers[0] = 1;
        fibonacciNumbers[1] = 1;

        for (int i = 2; i < n; i++) {
            fibonacciNumbers[i] = fibonacciNumbers[i-1] + fibonacciNumbers[i-2];
        }

        return fibonacciNumbers;
    }

    // Method to check if a number is prime
    private boolean isPrime(int number) {
        if (number < 2)
            return false;

        for (int i = 2; i <= Math.sqrt(number); i++) {
            if (number % i == 0) {
                return false;
            }
        }

        return true;
    }
}

