    try:
        upper_bound = int(upper_bound)
        if upper_bound <= lower_bound:
            print("Upper bound must be a positive integer greater than the lower bound.")
            return False
        return True
    except ValueError:
        print("Upper bound must be a positive integer greater than the lower bound.")
        return False

