    });
    req.on('end', () => {
      const parsedBody = querystring.parse(requestBody);
      res.writeHead(200, { 'Content-Type': 'text/plain' });
      res.end(`POST request received with data: ${JSON.stringify(parsedBody)}`);
    });
  } else if (req.method === 'PUT') {
