import math
import threading

def is_prime(n, primes):
    if n <= 1:
        return False
    if n in primes:
        return True
    for prime in primes:
        if prime * prime > n:
            break
        if n % prime == 0:
            return False
    return True

def sieve_of_atkin(n):
    if n < 2:
        return []

    sqrt_n = int(math.sqrt(n))
    primes = [2, 3]
    sieve = [False] * (n + 1)
    threads = []

    for x in range(1, sqrt_n + 1):
        for y in range(1, sqrt_n + 1):
            x2 = x * x
            y2 = y * y
            num = 4 * x2 + y2
            if num <= n and (num % 12 == 1 or num % 12 == 5):
                sieve[num] = not sieve[num]
            num = 3 * x2 + y2
            if num <= n and num % 12 == 7:
                sieve[num] = not sieve[num]
            num = 3 * x2 - y2
            if x > y and num <= n and num % 12 == 11:
                sieve[num] = not sieve[num]

    for x in range(5, sqrt_n):
        if sieve[x]:
            for y in range(x * x, n + 1, x * x):
                sieve[y] = False

    for x in range(5, n + 1):
        if sieve[x]:
            primes.append(x)

    prime_cache = set(primes)

    def find_primes(start, end):
        local_primes = []
        for num in range(start, end + 1):
            if is_prime(num, prime_cache):
                local_primes.append(num)
        with lock:
            results.extend(local_primes)

    num_threads = min(n, 10)
    chunk_size = int(math.ceil(n / num_threads))
    lock = threading.Lock()
    results = []
    for i in range(num_threads):
        start = i * chunk_size + 1
        end = min((i + 1) * chunk_size, n)
        thread = threading.Thread(target=find_primes, args=(start, end))
        threads.append(thread)
        thread.start()

    for thread in threads:
        thread.join()

    return sorted(results, reverse=True)

# Test the code
try:
    n = int(input("Enter a positive integer value for n: "))
    if n <= 0:
        raise ValueError("Invalid value for n")
    primes = sieve_of_atkin(n)
    print("Prime numbers from 1 to", n, "in descending order:", primes)
except ValueError as e:
    print("Error:", e)
```

