    words = [word for word in text if word not in common_words]

    # Counting the frequency of each keyword
    word_freq = {}
    for word in words:
        if word in word_freq:
            word_freq[word] += 1
        else:
            word_freq[word] = 1

    # Sorting the keywords based on frequency in descending order
    sorted_keywords = sorted(word_freq, key=lambda x: (word_freq[x], x), reverse=True)

