        result = {}
        self._flatten_recursive(self.data, '', result)
        return result

    def _flatten_recursive(self, data, prefix, result):
        if isinstance(data, dict):
            for key, value in data.items():
                new_prefix = f"{prefix}.{key}" if prefix else key
                self._flatten_recursive(value, new_prefix, result)
        elif isinstance(data, list):
            for index, value in enumerate(data):
                new_prefix = f"{prefix}.{index}" if prefix else str(index)
                self._flatten_recursive(value, new_prefix, result)
        else:
            result[prefix] = data

    def get_property_keys(self, depth):
        result = set()
        self._get_property_keys_recursive(self.data, '', depth, result)
        return result

    def _get_property_keys_recursive(self, data, prefix, depth, result):
        if depth == 0:
            return
        if isinstance(data, dict):
            for key, value in data.items():
                new_prefix = f"{prefix}.{key}" if prefix else key
                result.add(new_prefix)
                self._get_property_keys_recursive(value, new_prefix, depth - 1, result)
        elif isinstance(data, list):
            for index, value in enumerate(data):
                new_prefix = f"{prefix}.{index}" if prefix else str(index)
                self._get_property_keys_recursive(value, new_prefix, depth - 1, result)

    def get_parent_object(self, property_path):
        properties = property_path.split('.')
        current = self.data
        parent = None
        for prop in properties:
            if isinstance(current, dict) and prop in current:
                parent = current
                current = current[prop]
            elif isinstance(current, list):
                try:
                    prop = int(prop)
                    parent = current
                    current = current[prop]
                except (ValueError, IndexError):
                    parent = None
                    current = None
            else:
                parent = None
                current = None
            if current is None:
