def merge_json_objects(obj1, obj2):
    # Check if both objects have the same keys
    if obj1.keys() != obj2.keys():
        raise ValueError("Both objects must have the same keys")

    # Check if the "data" key in both objects is an array
    if not isinstance(obj1["data"], list) or not isinstance(obj2["data"], list):
        raise ValueError("The 'data' key in both objects must be an array")

    # Merge the "data" arrays of both objects into a single array
    merged_data = obj1["data"] + obj2["data"]

    # Custom sorting algorithm to sort the merged array in ascending order based on the values of the "name" key
    def custom_sort(arr):
        if len(arr) <= 1:
            return arr
        pivot = arr[len(arr) // 2]["name"]
        less = [x for x in arr if x["name"] < pivot]
        equal = [x for x in arr if x["name"] == pivot]
        greater = [x for x in arr if x["name"] > pivot]
        return custom_sort(less) + equal + custom_sort(greater)

    sorted_data = custom_sort(merged_data)

    # Custom function to remove duplicate entries from the merged array
    def remove_duplicates(arr):
        seen = set()
        result = []
        for item in arr:
            if item["name"] not in seen:
                seen.add(item["name"])
                result.append(item)
        return result

    merged_and_sorted_data = remove_duplicates(sorted_data)

    # Create a new object with the merged and sorted array as the "data" key's value
    new_obj = {}
    new_obj["data"] = merged_and_sorted_data

    # Assign the "name" key of the first object to the "name" key of the new object
    new_obj["name"] = obj1["name"]

    return new_obj
